    code: { lang: "python", title: "dicts.py — complete, runnable (Python 3.10+)", code: "attempts = {}\nfor user in [\"nadia\", \"rahim\", \"nadia\", \"admin\", \"nadia\"]:\n    attempts[user] = attempts.get(user, 0) + 1   # the counting idiom\nprint(\"Counts:\", attempts)\nprint(\"nadia:\", attempts[\"nadia\"], \"| guest:\", attempts.get(\"guest\", 0))\n\n# Iteration: keys, values, or pairs.\nfor user, count in attempts.items():\n    if count >= 3:\n        print(f\"WATCH: {user} ({count})\")\n\n# Nested dictionaries model real records: a user -> their facts.\nusers = {\n    \"nadia\": {\"fails\": 3, \"locked\": False},\n    \"rahim\": {\"fails\": 12, \"locked\": True},\n}\nprint(\"rahim locked?\", users[\"rahim\"][\"locked\"])\n\n# Merge with | (3.9+): defaults first, real values override.\ndefaults = {\"timeout\": 5, \"retries\": 2}\nconfig = defaults | {\"retries\": 4}\nprint(\"Config:\", config)\nprint(\"Keys:\", sorted(attempts.keys()))", output: "Counts: {'nadia': 3, 'rahim': 1, 'admin': 1}\nnadia: 3 | guest: 0\nWATCH: nadia (3)\nrahim locked? True\nConfig: {'timeout': 5, 'retries': 4}\nKeys: ['admin', 'nadia', 'rahim']", lines: ["The counting idiom runs five times: nadia is seen three times and lands at 3 — unseen names start from the default 0.", ".get('guest', 0) answers 0 instead of raising KeyError — the right behaviour for 'how many times did X happen?'", "users['rahim']['locked'] walks two levels: outer key to the record, inner key to the field.", "defaults | {'retries': 4}: retries is 4 in the result, while the defaults dict itself is unchanged — merge builds new."] },
