    code: { lang: "python", title: "password_tools.py — complete, runnable (Python 3.10+)", code: "import hashlib\nimport secrets\nimport string\n\n# secrets (not random) is the module built for passwords and tokens.\nalphabet = string.ascii_letters + string.digits\npassword = \"\".join(secrets.choice(alphabet) for _ in range(16))\nprint(\"Generated (yours will differ - that is the point):\", password)\nprint(\"Length:\", len(password))\n\n# Guess-space maths: alphabet_size ** length is the attacker's workload.\nfor length in (8, 12, 16):\n    space = len(alphabet) ** length\n    print(f\"Length {length}: {space:.2e} possibilities\")\n\n# Verify a login attempt against a stored SHA-256 of the real password.\nstored = hashlib.sha256(\"correct-horse-battery\".encode()).hexdigest()\nattempt = hashlib.sha256(\"correct-horse-battery\".encode()).hexdigest()\nprint(\"Attempt matches stored hash?\", secrets.compare_digest(attempt, stored))\nwrong = hashlib.sha256(\"Tr0ub4dor\".encode()).hexdigest()\nprint(\"Wrong attempt matches?\", secrets.compare_digest(wrong, stored))", output: "Generated (yours will differ - that is the point): <a fresh 16-character password>\nLength: 16\nLength 8: 2.18e+14 possibilities\nLength 12: 3.23e+21 possibilities\nLength 16: 4.77e+28 possibilities\nAttempt matches stored hash? True\nWrong attempt matches? False", lines: ["The generated password is the one line whose exact text cannot be predicted — unpredictability is the feature being demonstrated.", "The space table is the strength argument in numbers: length 8 is a GPU afternoon; length 16 is astronomy.", "compare_digest answered True/False without ever comparing the PASSWORDS — only their hashes meet.", "The stored value is a hash: a stolen copy of it does not directly log anyone in (and a slow KDF would make guessing it expensive — the production upgrade)."] },
